import { flexRender } from '@tanstack/react-table';
import clsx from 'clsx';
import React from 'react';

import { alignmentOptionsCSS } from './alignment-variant.sty.js';
import { dataTableV2CellCSS } from './DataTableV2Cell.sty.js';
import { type StylingProps } from '../../../core/types/styling-props.js';
import { useDataTableV2 } from '../contexts/DataTableV2Context.js';
import { DATA_TABLE_V2_DEFAULT_CELL_ALIGNMENT } from '../features/ColumnAlignment.js';
import { getCellTypeRenderer } from '../features/ColumnTypes.js';
import { _UserActionsMenuWrapper } from '../features/UserActions.js';
import { type Cell } from '../hooks/useTable/types.js';

interface DataTableV2CellProps<TData, TValue> extends StylingProps {
  cell: Cell<TData, TValue>;

  /**
   * Measure function that is called when the cell is
   * rendered to the dom.
   */
  measure: (element: Element | null) => void;

  /**
   * Column index in order to map it to the cells data attributes for identification.
   */
  columnIndex: number;
  /**
   * Row index in order to map it to the cells data attributes for identification.
   */
  rowIndex: number;
}

export function DataTableV2Cell<TData, TValue>(
  props: DataTableV2CellProps<TData, TValue>,
): JSX.Element | null {
  const {
    cell,
    measure,
    style,
    className: consumerClassName,
    rowIndex,
    columnIndex,
    ...remainingProps
  } = props;

  const table = useDataTableV2();

  const visualVariantOptions = table.getVisualVariantOptions();

  const hasCellActions = cell.getCanCellUserActions();

  const columnDef = cell.column.columnDef;

  // check if column has has custom renderer?
  const defaultCellRenderer = columnDef.columnType
    ? getCellTypeRenderer(columnDef.columnType)
    : table._getDefaultColumnDef().cell;
  const isCustomRenderer =
    !columnDef.meta?.hasFormatter && columnDef.cell !== defaultCellRenderer;

  const baseProps = {
    role: 'cell',
    className: clsx(
      dataTableV2CellCSS({
        lineWrap: cell.column.getIsLineWrapped(),
        fontStyle: visualVariantOptions.fontStyle,
        rowSeparation: visualVariantOptions.rowSeparation,
        rowDensity: visualVariantOptions.rowDensity,
        customRenderer: isCustomRenderer,
        verticalDividers: visualVariantOptions.verticalDividers,
        rowParity: rowIndex % 2 === 0 ? 'even' : 'odd',
        loading: table.getState().loading,
      }),
      alignmentOptionsCSS[
        columnDef.alignment ?? DATA_TABLE_V2_DEFAULT_CELL_ALIGNMENT
      ],
      consumerClassName,
    ),
    ref: measure,
    'data-index': `row-${rowIndex}-colummn-${columnIndex}`,
    'data-row': rowIndex,
    'data-column': columnIndex,
    style: style,
    ...remainingProps,
    children: flexRender(columnDef.cell, cell.getContext()),
  };

  if (!hasCellActions) {
    return <div {...baseProps} />;
  }

  const actions = cell.getCellUserActions();

  return (
    // eslint-disable-next-line react/jsx-pascal-case
    <_UserActionsMenuWrapper
      {...baseProps}
      actions={actions}
      column={hasCellActions ? cell.column : null}
    />
  );
}
